17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.CityCapacityExceededException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.samples.petclinic.util.AddressNormalizer;
43	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
44	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /** Maximum number of owners a single city may contain; creating an owner in a city that
63	     *  already has this many owners is rejected with 409 Conflict. */
64	    private static final int MAX_OWNERS_PER_CITY = 50;
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final TelephoneNormalizer telephoneNormalizer;
75	
76	    private final HouseholdNormalizer householdNormalizer;
77	
78	    private final AddressNormalizer addressNormalizer;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper,
84	                                 TelephoneNormalizer telephoneNormalizer,
85	                                 HouseholdNormalizer householdNormalizer,
86	                                 AddressNormalizer addressNormalizer) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	        this.telephoneNormalizer = telephoneNormalizer;
92	        this.householdNormalizer = householdNormalizer;
93	        this.addressNormalizer = addressNormalizer;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        normalizeOwnerFields(owner);
127	        // Reject creating an owner when the owner's city already contains 50 or more owners.
128	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
129	            throw new CityCapacityExceededException(
130	                "The city " + owner.getCity() + " already contains the maximum number of owners");
131	        }
132	        // Reject creating an owner whose normalized telephone is already used by another owner.
133	        String normalizedTelephone = owner.getTelephone();
134	        if (isTelephoneInUse(normalizedTelephone)) {
135	            throw new DuplicateTelephoneException(
136	                "An owner with telephone " + normalizedTelephone + " already exists");
137	        }
138	        // Identify any existing owners who share a household (same last name and address,
139	        // compared case-insensitively with collapsed whitespace) with the owner being created.
140	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
141	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
142	        // Reject creating an owner who shares a household with an existing owner, unless the
143	        // request explicitly opts in with 'sharesHousehold' true.
144	        if (!sharesHousehold && !householdMembers.isEmpty()) {
145	            throw new DuplicateHouseholdException(
146	                "An owner with the same last name and address already exists");
147	        }
148	        // When opting in and joining an existing household, assign the new owner and every
149	        // existing member the same stable household identifier derived from the last name and
150	        // address, so all owners of the household share one 'householdId'.
151	        if (sharesHousehold && !householdMembers.isEmpty()) {
152	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
153	            owner.setHouseholdId(householdId);
154	            for (Owner member : householdMembers) {
155	                if (!householdId.equals(member.getHouseholdId())) {
156	                    member.setHouseholdId(householdId);
157	                    this.clinicService.saveOwner(member);
158	                }
159	            }
160	        }
161	        // Record how many existing owners already share this owner's first and last name
162	        // (compared case-insensitively) before this create, fixed at creation time.
163	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
164	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' from the city, last name and a
165	        // per-city sequence equal to one more than the owners already in that city, fixed at
166	        // creation time.
167	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
168	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
169	        // of the registration date's year (e.g. 'LON-SMI-0007-M26'), fixed at creation time.
170	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
171	        this.clinicService.saveOwner(owner);
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    /**
179	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
180	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
181	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
182	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
183	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
184	     * server's current date. Canonicalising the address here, before the household checks read it,
185	     * ensures duplicate detection and the shared household id both compare the normalized form.
186	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
187	     * duplicate, household and customer-code rules.
188	     *
189	     * @param owner the newly mapped owner to canonicalize
190	     */
191	    private void normalizeOwnerFields(Owner owner) {
192	        // Normalize the address on create so it is stored and returned in canonical form and every
193	        // later comparison (household duplicate detection and the shared household id) uses it.
194	        // A value that is blank after normalization is rejected with 400.
195	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
196	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
197	        // A value that cannot form a valid E.164 number is rejected with 400.
198	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
199	        // Store the (already syntactically validated) email lower-cased so it is persisted and
200	        // returned in canonical form. A missing email is left untouched.
201	        owner.setEmail(normalizeEmail(owner.getEmail()));
202	        // Default the registration date to the server's current date when the client did not
203	        // supply one, so it is persisted and returned in ISO 'YYYY-MM-DD' form.
204	        if (owner.getRegistrationDate() == null) {
205	            owner.setRegistrationDate(java.time.LocalDate.now());
206	        }
207	    }
208	
209	    /**
210	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
211	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
212	     * syntactically valid address (rejecting anything else with 400).
213	     *
214	     * @param email the email value (may be {@code null})
215	     * @return the lower-cased email, or {@code null} if the input was {@code null}
216	     */
217	    private String normalizeEmail(String email) {
218	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
219	    }
220	
221	    /**
222	     * Builds the customer code '<CITY3>-<LAST3>-<NNNN>' for a newly created owner, where CITY3 is
223	     * the upper-cased first three letters of the city, LAST3 is the upper-cased first three letters
224	     * of the last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than
225	     * the owners already in that city (e.g. 'LON-SMI-0007').
226	     *
227	     * @param city     the owner's city
228	     * @param lastName the owner's last name
229	     * @return the formatted customer code
230	     */
231	    private String nextCustomerCode(String city, String lastName) {
232	        String cityPrefix = city.substring(0, Math.min(3, city.length()))
233	            .toUpperCase(java.util.Locale.ROOT);
234	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length()))
235	            .toUpperCase(java.util.Locale.ROOT);
236	        int sequence = countOwnersInCity(city) + 1;
237	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
238	    }
239	
240	    /**
241	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
242	     * fix the per-city sequence of an owner's customer code at creation time.
243	     *
244	     * @param city the city of the owner being created
245	     * @return the number of existing owners in a matching city
246	     */
247	    private int countOwnersInCity(String city) {
248	        return (int) this.clinicService.findAllOwners().stream()
249	            .filter(existing -> existing.getCity() != null
250	                && existing.getCity().equalsIgnoreCase(city))
251	            .count();
252	    }
253	
254	    /**
255	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
256	     * the last two digits of the registration date's year (e.g. 'LON-SMI-0007-M26').
257	     *
258	     * @param customerCode     the owner's customer code
259	     * @param registrationDate the owner's registration date
260	     * @return the formatted membership number
261	     */
262	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
263	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
264	    }
265	
266	    /**
267	     * Determines whether the given normalized telephone is already used by an existing owner.
268	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
269	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
270	     * as the same number.
271	     *
272	     * @param normalizedTelephone the normalized (E.164) telephone to look for
273	     * @return {@code true} if another owner already uses this telephone
274	     */
275	    private boolean isTelephoneInUse(String normalizedTelephone) {
276	        if (normalizedTelephone == null) {
277	            return false;
278	        }
279	        return this.clinicService.findAllOwners().stream()
280	            .map(Owner::getTelephone)
281	            .map(telephoneNormalizer::normalize)
282	            .anyMatch(normalizedTelephone::equals);
283	    }
284	
285	    /**
286	     * Returns the existing owners who share the given household, i.e. have the same last name and
287	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
288	     * differing only in letter case or in incidental whitespace are treated as the same household.
289	     *
290	     * @param lastName the last name of the owner being created
291	     * @param address  the address of the owner being created
292	     * @return the existing owners with a matching last name and address (possibly empty)
293	     */
294	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
295	        String householdKey = householdNormalizer.householdKey(lastName, address);
296	        return this.clinicService.findAllOwners().stream()
297	            .filter(existing -> householdNormalizer
298	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
299	            .toList();
300	    }
301	
302	    /**
303	     * Counts the existing owners who share the given first and last name, compared
304	     * case-insensitively. Used to fix an owner's namesake count at creation time.
305	     *
306	     * @param firstName the first name of the owner being created
307	     * @param lastName  the last name of the owner being created
308	     * @return the number of existing owners with a matching first and last name
309	     */
310	    private int countNamesakes(String firstName, String lastName) {
311	        return (int) this.clinicService.findAllOwners().stream()
312	            .filter(existing -> existing.getFirstName() != null
313	                && existing.getFirstName().equalsIgnoreCase(firstName)
314	                && existing.getLastName() != null
315	                && existing.getLastName().equalsIgnoreCase(lastName))
316	            .count();
317	    }
318	
319	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
320	    @Override
321	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
322	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
323	        if (currentOwner == null) {
324	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
325	        }
326	        currentOwner.setAddress(ownerFieldsDto.getAddress());
327	        currentOwner.setCity(ownerFieldsDto.getCity());
328	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
329	        currentOwner.setLastName(ownerFieldsDto.getLastName());
330	        // Normalize the telephone to canonical E.164 form so it is stored and returned
331	        // consistently with create; an unformattable value is rejected with 400.
332	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
333	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
334	        this.clinicService.saveOwner(currentOwner);
335	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
336	    }
337	
338	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
339	    @Transactional
340	    @Override
341	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
342	        Owner owner = this.clinicService.findOwnerById(ownerId);
343	        if (owner == null) {
344	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
345	        }
346	        this.clinicService.deleteOwner(owner);
347	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
348	    }
349	
350	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
351	    @Override
352	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
353	        Owner owner = this.clinicService.findOwnerById(ownerId);
354	        if (owner == null) {
355	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
356	        }
357	        HttpHeaders headers = new HttpHeaders();
358	        Pet pet = petMapper.toPet(petFieldsDto);
359	        owner.setId(ownerId);
360	        pet.setOwner(owner);
361	        pet.getType().setName(null);
362	        this.clinicService.savePet(pet);
363	        PetDto petDto = petMapper.toPetDto(pet);
364	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
365	            .buildAndExpand(pet.getId()).toUri());
366	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
367	    }
368	
369	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
370	    @Override
371	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
372	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
373	        if (currentOwner != null) {
374	            Pet currentPet = this.clinicService.findPetById(petId);
375	            if (currentPet != null) {
376	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
377	                currentPet.setName(petFieldsDto.getName());
378	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
379	                this.clinicService.savePet(currentPet);
380	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
381	            }
382	        }
383	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
384	    }
385	
386	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
387	    @Override
388	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
389	        HttpHeaders headers = new HttpHeaders();
390	        Visit visit = visitMapper.toVisit(visitFieldsDto);
391	        Pet pet = new Pet();
392	        pet.setId(petId);
393	        visit.setPet(pet);
394	        this.clinicService.saveVisit(visit);
395	        VisitDto visitDto = visitMapper.toVisitDto(visit);
396	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
397	            .buildAndExpand(visit.getId()).toUri());
398	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
399	    }
400	
401	
402	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
403	    @Override
404	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
405	        Owner owner = this.clinicService.findOwnerById(ownerId);
406	        if (owner != null) {
407	            Pet pet = owner.getPet(petId);
408	            if (pet != null) {
409	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
410	            }
411	        }
412	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
413	    }
414	}
