41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the same telephone already exists";
57	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the same last name and address already exists";
58	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
59	    private static final String ERROR_INVALID_TELEPHONE = "The supplied telephone number is not a valid E.164 number";
60	    private static final String ERROR_INVALID_ADDRESS = "The supplied address is blank after normalization";
61	
62	    /**
63	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
64	     * class.
65	     *
66	     * @param e     Object referring to the thrown exception.
67	     * @param status HTTP response status.
68	     * @param url URL request.
69	     */
70	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
71	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
72	        problemDetail.setType(URI.create(url.toString()));
73	        problemDetail.setTitle(e.getClass().getSimpleName());
74	        problemDetail.setDetail(detail);
75	        problemDetail.setProperty("timestamp", Instant.now());
76	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
77	        return problemDetail;
78	    }
79	
80	    /**
81	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
82	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
83	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
84	     * would catch it and report an authorization failure as a 500.
85	     *
86	     * @param e The {@link AccessDeniedException} to propagate
87	     * @throws AccessDeniedException always
88	     */
89	    @ExceptionHandler(AccessDeniedException.class)
90	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
91	        throw e;
92	    }
93	
94	    /**
95	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
96	     *
97	     * @param e The {@link Exception} to be handled
98	     * @param request {@link HttpServletRequest} object referring to the current request.
99	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
100	     */
101	    @ExceptionHandler(Exception.class)
102	    @ResponseBody
103	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
104	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
105	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
106	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
107	        return ResponseEntity.status(status).body(detail);
108	    }
109	
110	    /**
111	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
112	     * method returns a 404 Not Found status if an entity does not exist.
113	     *
114	     * @param e The {@link DataIntegrityViolationException} to be handled
115	     * @param request {@link HttpServletRequest} object referring to the current request.
116	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
117	     */
118	    @ExceptionHandler(DataIntegrityViolationException.class)
119	    @ResponseBody
120	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
121	        logger.warn("Data integrity violation at {} {}: {}",
122	            request.getMethod(),
123	            request.getRequestURI(),
124	            e.getMessage());
125	        logger.debug("Data integrity violation stacktrace", e);
126	        HttpStatus status = HttpStatus.NOT_FOUND;
127	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
128	        return ResponseEntity.status(status).body(detail);
129	    }
130	
131	    /**
132	     * Handles {@link DuplicateTelephoneException}, raised when an owner is created with a normalized
133	     * telephone that is already used by another owner, returning a 409 Conflict status.
134	     *
135	     * @param e The {@link DuplicateTelephoneException} to be handled
136	     * @param request {@link HttpServletRequest} object referring to the current request.
137	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
138	     */
139	    @ExceptionHandler(DuplicateTelephoneException.class)
140	    @ResponseBody
141	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
142	        logger.warn("Duplicate telephone at {} {}: {}",
143	            request.getMethod(),
144	            request.getRequestURI(),
145	            e.getMessage());
146	        HttpStatus status = HttpStatus.CONFLICT;
147	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
148	        return ResponseEntity.status(status).body(detail);
149	    }
150	
151	    /**
152	     * Handles {@link DuplicateHouseholdException}, raised when an owner is created whose last name
153	     * and address already match another owner (and the request did not opt in with
154	     * {@code sharesHousehold=true}), returning a 409 Conflict status.
155	     *
156	     * @param e The {@link DuplicateHouseholdException} to be handled
157	     * @param request {@link HttpServletRequest} object referring to the current request.
158	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
159	     */
160	    @ExceptionHandler(DuplicateHouseholdException.class)
161	    @ResponseBody
162	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
163	        logger.warn("Duplicate household at {} {}: {}",
164	            request.getMethod(),
165	            request.getRequestURI(),
166	            e.getMessage());
167	        HttpStatus status = HttpStatus.CONFLICT;
168	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
169	        return ResponseEntity.status(status).body(detail);
170	    }
171	
172	    /**
173	     * Handles {@link CityCapacityExceededException}, raised when an owner is created in a city that
174	     * already contains 50 or more owners, returning a 409 Conflict status.
175	     *
176	     * @param e The {@link CityCapacityExceededException} to be handled
177	     * @param request {@link HttpServletRequest} object referring to the current request.
178	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
179	     */
180	    @ExceptionHandler(CityCapacityExceededException.class)
181	    @ResponseBody
182	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
183	        logger.warn("City at capacity at {} {}: {}",
184	            request.getMethod(),
185	            request.getRequestURI(),
186	            e.getMessage());
187	        HttpStatus status = HttpStatus.CONFLICT;
188	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
189	        return ResponseEntity.status(status).body(detail);
190	    }
191	
192	    /**
193	     * Handles {@link InvalidTelephoneException}, raised when a supplied telephone value cannot be
194	     * normalized to a valid E.164 number, returning a 400 Bad Request status.
195	     *
196	     * @param e The {@link InvalidTelephoneException} to be handled
197	     * @param request {@link HttpServletRequest} object referring to the current request.
198	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
199	     */
200	    @ExceptionHandler(InvalidTelephoneException.class)
201	    @ResponseBody
202	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
203	        logger.warn("Invalid telephone at {} {}: {}",
204	            request.getMethod(),
205	            request.getRequestURI(),
206	            e.getMessage());
207	        HttpStatus status = HttpStatus.BAD_REQUEST;
208	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_TELEPHONE);
209	        return ResponseEntity.status(status).body(detail);
210	    }
211	
212	    /**
213	     * Handles {@link InvalidAddressException}, raised when a supplied address value is blank after
214	     * normalization (and so carries no address), returning a 400 Bad Request status.
215	     *
216	     * @param e The {@link InvalidAddressException} to be handled
217	     * @param request {@link HttpServletRequest} object referring to the current request.
218	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
219	     */
220	    @ExceptionHandler(InvalidAddressException.class)
221	    @ResponseBody
222	    public ResponseEntity<ProblemDetail> handleInvalidAddressException(InvalidAddressException e, HttpServletRequest request) {
223	        logger.warn("Invalid address at {} {}: {}",
224	            request.getMethod(),
225	            request.getRequestURI(),
226	            e.getMessage());
227	        HttpStatus status = HttpStatus.BAD_REQUEST;
228	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_ADDRESS);
229	        return ResponseEntity.status(status).body(detail);
230	    }
231	
232	    /**
233	     * Handles exception thrown by Bean Validation on controller methods parameters
234	     *
235	     * @param e The {@link MethodArgumentNotValidException} to be handled
236	     * @param request {@link HttpServletRequest} object referring to the current request.
237	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
238	     */
239	    @ExceptionHandler(MethodArgumentNotValidException.class)
240	    @ResponseBody
241	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
242	        HttpStatus status = HttpStatus.BAD_REQUEST;
243	        BindingErrorsResponse errors = new BindingErrorsResponse();
244	        BindingResult bindingResult = e.getBindingResult();
245	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
246	        if (bindingResult.hasErrors()) {
247	            errors.addAllErrors(bindingResult);
248	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
249	                .map(fieldError -> {
250	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
251	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
252	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
253	                        fieldError.getField(),
254	                        defaultMessage,
255	                        rejectedValue);
256	                    return new ValidationMessageDto(message)
257	                        .putAdditionalProperty("field", fieldError.getField())
258	                        .putAdditionalProperty("rejectedValue", rejectedValue)
259	                        .putAdditionalProperty("defaultMessage", defaultMessage);
260	                })
261	                .toList();
262	            logger.debug("Validation error at {} {}: {}",
263	                request.getMethod(),
264	                request.getRequestURI(),
265	                bindingResult.getFieldErrors());
266	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
267	            detail.setProperty("errors", rejectedFieldNames(bindingResult));
